def running_max(values):
    out=[]
    for v in values: out.append(max(v,out[-1]) if out else v)
    return out

def nonzero_runs(values):
    out=[]; n=0
    for v in values:
     if v: n+=1
     elif n: out.append(n); n=0
    if n: out.append(n)
    return out

def first_repeat_index(values):
    seen=set()
    for i,v in enumerate(values):
     if v in seen: return i
     seen.add(v)
    return -1

def collapse_hyphens(text):
    import re
    return re.sub("-+","-",text)

def parenthesis_balance(text):
    n=0
    for c in text:
     n+=(c=="(")-(c==")")
     if n<0:return False
    return n==0

def invert_unique(mapping):
    out={}
    for k,v in mapping.items():
     if v in out:raise ValueError
     out[v]=k
    return out

